SELECT CASE WHEN budget >= 3254000 THEN 'high' WHEN budget >= 1554000 THEN 'mid' ELSE 'low' END AS budget_bucket, SUM(CASE WHEN location = 'Singapore' THEN budget ELSE 0 END) AS singapore_budget FROM departments WHERE dept_name = 'Finance' AND budget < 3097000 GROUP BY 1 HAVING singapore_budget >= 60
